"""Sort the given models based on their dependencies. It uses a depth-first search to sort the models based on their dependencies and returns the sorted list of models.

:param models: List. A list of model instances to be sorted.
:return: List. The sorted list of model instances based on their dependencies.
"""
# Create a graph of models and their dependencies.
graph = defaultdict(set)
for model in models:
    for field in model._meta.sorted_fields:
        if isinstance(field, ForeignKeyField):
            graph[model].add(field.rel_model)

# Perform a depth-first search to sort the models based on their dependencies.
sorted_models = []
visited = set()

def dfs(model):
    if model in visited:
        return
    visited.add(model)
    for dependency in graph[model]:
        dfs(dependency)
    sorted_models.append(model)

for model in models:
    dfs(model)

return sorted_models

"""It returns the SHA-256 hash of the public key in the given certificate.

:param certificate: Certificate. The input certificate from which the public key is extracted.
:return: bytes. The SHA-256 hash of the public key.
"""
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric import ed25519
from cryptography.hazmat.primitives.asymmetric import x25519
from cryptography.hazmat.primitives.asymmetric import x448
from cryptography.hazmat.primitives.asymmetric import dsa
from cryptography.hazmat.primitives.asymmetric import utils

try:
    public_key = certificate.public_key()
except ValueError:
    # Cryptography could not parse the certificate https://github.com/nabla-c0d3/sslyze/pull/495
    return b""

if isinstance(public_key, rsa.RSAPublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils.EncryptionAlgorithm.PKCS1v15()))
elif isinstance(public_key, ec.EllipticCurvePublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils.PublicFormat.SubjectPublicKeyInfo))
elif isinstance(public_key, ed25519.Ed25519PublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils.PublicFormat.SubjectPublicBytesFormat))
elif isinstance(public_key, x25519.X25519PublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils._X25519PublicFormat.Raw))
elif isinstance(public_key, x448.X448PublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils._X448PublicFormat.Raw))
elif isinstance(public_key, dsa.DSAPublicKey):
    return utils.sha256(public_key.public_bytes(utils.Encoding.DER, utils.Encoding.PEM))
else:
    return b""

