if not value.isascii():
    raise ValueError("value must contain only US-ASCII characters")

self._headers[name] = value

"""This function implements the command `unhide` which restores a unit definition that was hidden from the AST. It takes input arguments and performs certain actions based on the input. Initially, the function checks if the number of command tokens is less than three. It determines the unit type from the second command token and validate the type of unit. It tries to interpret the third command token as a regular expression and execute the restoration process on the unit with different regular expression conditions.

:param self: UnhideCommand. An instance of the UnhideCommand class.
:return: No return values.
"""
if len(self.tokens) < 3:
    self.print_error("Not enough arguments.")
    return

unit_type = get_unit_type_from_str(self.tokens[1])
if unit_type is None:
    self.print_error("Invalid unit type.")
    return

if unit_type == UnitType.alias:
    self.print_error("Aliases cannot be restored.")
    return

if unit_type == UnitType.slot:
    self.print_error("Slots cannot be restored.")
    return

if unit_type == UnitType.intent:
    self.print_error("Intents cannot be restored.")
    return

try:
    regex = re.compile(self.tokens[2])
except re.error:
    self.print_error("Invalid regular expression.")
    return

for unit in self.project.units:
    if unit.type == unit_type:
        if regex.match(unit.name):
            unit.hidden = False
            self.print_success(f"Unit {unit.name} restored.")

"""This function reduces any extra accidentals in a given note to proper notes.


:param note: String. The note with accidentals
:return: String. The reduced note without extra accidentals.

"""
if note[0] == "A":
    if note[1] == "#":
        return "B" + note[2:]
    elif note[1] == "b":
        return "G" + note[2:]
    else:
        return note
elif note[0] == "B":
    if note[1] == "#":
        return "C" + note[2:]
    elif note[1] == "b":
        return "A" + note[2:]
    else:
        return note
elif note[0] == "C":
    if note[1] == "#":
        return "D" + note[2:]
    elif note[1] == "b":
        return "B" + note[2:]
    else:
        return note
elif note[0] == "D":
    if note[1] == "#":
        return "E" + note[2:]
    elif note[1] == "b":
        return "C" + note[2:]
    else:
        return note
elif note[0] == "E":
    if note[1] == "#":
        return "F" + note[2:]
    elif note[1] == "b":
        return "D" + note[2:]
    else:
        return note
elif note[0] == "F":
    if note[1] == "#":
        return "G" + note[2:]
    elif note[1] == "b":
        return "E" + note[2:]
    else:
        return note
