"""
if data.entry_point_name!= data.ext_name:
    logger.warning(
        "Extension %s has an invalid entry point name %s. It should be %s.",
        data.ext_name,
        data.entry_point_name,
        data.ext_name,
    )
    return False

if data.dependencies:
    missing_deps = [dep for dep in data.dependencies if not pkg_resources.resource_exists(dep, "")]
    if missing_deps:
        logger.warning(
            "Extension %s has missing dependencies %s.",
            data.ext_name,
            ", ".join(missing_deps),
        )
        return False

if data.environment:
    missing_env = [env for env in data.environment if env not in os.environ]
    if missing_env:
        logger.warning(
            "Extension %s has missing environment variables %s.",
            data.ext_name,
            ", ".join(missing_env),
        )
        return False

if data.config_schema:
    try:
        data.config_schema.validate({})
    except jsonschema.ValidationError as e:
        logger.warning(
            "Extension %s has an invalid config schema: %s.",
            data.ext_name,
            e,
        )
        return False

if data.default_config:
    try:
        data.default_config.validate({})
    except jsonschema.ValidationError as e:
        logger.warning(
            "Extension %s has an invalid default config: %s.",
            data.ext_name,
            e,
        )
        return False

return True

