if self.remaining_budget() < self.privacy.privacy_budget_error:
    raise ValueError(
        f"Privacy spend of ({epsilon},{delta}) not permissible; will exceed remaining privacy {self.privacy.__class__.__name__} budget. Use {self.privacy.__class__.__name__}.{self.privacy.remaining_budget.__name__}() to check remaining budget."
    )

if self.remaining_budget() < self.privacy.privacy_budget:
    raise ValueError(
        f"Privacy spend of ({epsilon},{delta}) not permissible; will exceed remaining privacy {self.privacy.__class__} budget. Use {self.privacy.__class__}.{self.privacy.remaining_budget.__name__}() to check remaining budget."
    )

if self.remaining_budget() < self.epsilon_delta_to_budget(epsilon, delta):
    raise ValueError(
        f"Privacy spend of ({epsilon},{delta}) not permissible; will exceed remaining privacy budget. Use {self.__class__}.{self.epsilon_delta_to_budget.__name__}() to check remaining budget."
    )

return True

"""This function normalizes the search criteria by converting them into a standardized format. It handles different types of criteria and converts them accordingly including "int, str, datatime, list, tuple, bytes". If no criteria are specified, it raises the corresponding error. If no character set is specified, it defaults to "us-ascii".

:param criteria: The search criteria to be normalized. It can be a string, bytes, list, tuple, int, datetime, or date.
:param charset: The character set to be used for encoding. Defaults to "us-ascii" if not specified.
:return: A list of normalized search criteria.
"""
if criteria is None:
    raise ValueError("No search criteria specified.")
if isinstance(criteria, (str, bytes)):
    criteria = (criteria,)
elif isinstance(criteria, (list, tuple)):
    criteria = tuple(criteria)
elif isinstance(criteria, int):
    criteria = (criteria,)
elif isinstance(criteria, datetime):
    criteria = (criteria,)
elif isinstance(criteria, date):
    criteria = (criteria,)
elif isinstance(criteria, bytes):
    criteria = (criteria,)
else:
    raise ValueError("Invalid search criteria type.")
if charset is None:
    charset = "us-ascii"
return [to_bytes(c, charset) for c in criteria]

