"""The function creates a concrete Choice instance based on the current state of the ChoiceBuilder object. It first checks if all the necessary information is provided, and then constructs a Choice object using the leading space, modifiers representation, and rules of the ChoiceBuilder object.

:param self: ChoiceBuilder. An instance of the ChoiceBuilder class.
:return: Choice. The created Choice instance.
"""
if self.unit_type is None:
    raise ValueError("The unit type is not set.")
if self.unit_name is None:
    raise ValueError("The unit name is not set.")
if self.unit_name == "":
    raise ValueError("The unit name is empty.")
if self.leading_space is None:
    raise ValueError("The leading space is not set.")
if self.modifiers is None:
    raise ValueError("The modifiers are not set.")
if self.rules is None:
    raise ValueError("The rules are not set.")
if self.unit_type == UnitType.alias:
    if self.alias_name is None:
        raise ValueError("The alias name is not set.")
    if self.alias_name == "":
        raise ValueError("The alias name is empty.")
    if self.alias_name == self.unit_name:
        raise ValueError("The alias name is the same as the unit name.")
    if self.alias_name in self.rules:
        raise ValueError("The alias name is already used.")
if self.unit_type == UnitType.slot:
    if self.slot_name is None:
        raise ValueError("The slot name is not set.")
    if self.slot_name == "":
        raise ValueError("The slot name is empty.")
    if self.slot_name in self.rules:
        raise ValueError("The slot name is already used.")
if self.unit_type == UnitType.intent:
    if self.intent_name is None:
        raise ValueError("The intent name is not set.")
    if self.intent_name == "":
        raise ValueError("The intent name is empty.")
    if self.intent_name in self.rules:
        raise ValueError("The intent name is already used.")
if self.unit_type == UnitType.alias:
    return Alias(
        self.unit_name,
        self.alias_name,
        self.leading_space,
        self.modifiers,
        self.rules,
    )
if self.unit_type == UnitType.slot:
    return Slot(
        self.unit_name,
        self.slot_name,
        self.leading_space,
        self.modifiers,
        self.rules,
    )
if self.unit_type == Unit_Type.intent:
    return Intent(
        self.unit_name,
        self.intent_name,
        self.leading_space,
        self.modifiers,
        self.rules,
    )
raise ValueError("The unit type is invalid.")

