if select_for_downgrade:
    if upper.down_revision is None:
        return
    if lower.down_revision is None:
        return
    if upper.down_revision == lower:
        return

if assert_relative_length:
    assert len(self.get_revisions(upper, lower)) == len(
        self.get_revisions(lower, upper)
    )

if select_for_downgrade:
    for rev in self.get_revisions(lower, upper):
        yield rev
else:
    for rev in self.get_revisions(upper, lower):
        yield rev

