        )
    if untagged_response[0] == b"PREAUTH":
        raise exceptions.IMAPClientError(
            "Server returned PREAUTH response: %s" % untagged_response[1]
        )
    if untagged_response[0] == b"CAPABILITY":
        raise exceptions.IMAPClientError(
            "Server returned CAPABILITY response: %s" % untagged_response[1]
        )
    if untagged_response[0] == b"AUTHENTICATE":
        raise exceptions.IMAPClientError(
            "Server returned AUTHENTICATE response: %s" % untagged_response[1]
        )
    if untagged_response[0] == b"STARTTLS":
        raise exceptions.IMAPClientError(
            "Server returned STARTTLS response: %s" % untagged_response[1]
        )
    if untagged_response[0] == b"INFO":
